<body><main><h1>User Management</h1><p>Manage roles, passwords, profile pictures, and book history.</p><p class="success">Passwords are protected and are never displayed. Select Edit to set or change a user's password.</p>@if(session('success'))<p class="success">{{ session('success') }}</p>@endif<a href="{{ route('users.create') }}">Add user</a> <a href="{{ url('/admin/dashboard') }}">Dashboard</a>@foreach(['admin'=>'Administrators','staff'=>'Staff','student'=>'Students'] as $role=>$heading)<h2 style="margin:30px 0 0;padding:12px 14px;background:#111b35;color:#8eafff;font-size:20px;border-left:4px solid {{ $role==='admin'?'#7448c8':($role==='staff'?'#219653':'#3774ff') }}">{{ $heading }} <span style="float:right;font-size:13px;color:#aeb9d4;font-weight:400">{{ $users->where('role',$role)->count() }}</span></h2><table><thead><tr><th>Name</th><th>Email</th><th>Password</th><th>Actions</th></tr></thead><tbody>@forelse($users->where('role',$role) as $user)<tr><td>{{ $user->name }}</td><td>{{ $user->email }}</td><td>Protected</td><td><div class="actions"><a href="{{ route('users.edit',$user) }}">Edit / Change password</a>@if(in_array($user->role,['staff','student'],true))<a href="{{ route('users.history',$user) }}">Book history</a>@endif<form method="POST" action="{{ route('users.destroy',$user) }}">@csrf @method('DELETE')<button class="danger" type="submit">Delete</button></form></div></td></tr>@empty<tr><td colspan="4">No {{ strtolower($heading) }} found.</td></tr>@endforelse</tbody></table>@endforeach</main></body></html>
